"""Command line entry for the multi-agent prototype."""

from __future__ import annotations

import argparse
from pathlib import Path

from eval.runner import load_tasks, run_suite
from src.config import PROJECT_ROOT, load_dotenv
from src.orchestrator.hitl import CLIHuman, ScriptedHuman
from src.orchestrator.runner import Platform

DEMO_GOAL = (
    "Write a Markdown report listing the first 15 Fibonacci numbers, "
    "generated by a Python script."
)


def _print_summary(record) -> None:
    print()
    print(
        f"Result {record.task_id}: completion {record.completion_rate:.0%}, "
        f"{record.seconds:.3f}s, fatal={'yes' if record.fatal else 'no'}, "
        f"success={'yes' if record.success else 'no'}"
    )


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Multi-agent collaborative platform prototype")
    parser.add_argument(
        "--online",
        action="store_true",
        help="Allow the search tool to call DuckDuckGo. The default is an offline note.",
    )
    parser.add_argument(
        "--provider",
        choices=("mock", "deepseek", "hkgai"),
        help="Override LLM_PROVIDER for this process.",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    sub.add_parser("demo", help="Run the Fibonacci group-chat scenario with the mock model")

    task = sub.add_parser("task", help="Give a goal to the group")
    task.add_argument("goal")
    task.add_argument(
        "--scripted",
        action="store_true",
        help="Answer human prompts automatically instead of waiting for input.",
    )

    direct = sub.add_parser("dm", help="Send a private message to one agent")
    direct.add_argument("agent", choices=("researcher", "coder", "reviewer"))
    direct.add_argument("goal")
    direct.add_argument("--scripted", action="store_true")

    evaluation = sub.add_parser("eval", help="Run a JSON task list and write a performance report")
    evaluation.add_argument(
        "--tasks",
        default=str(PROJECT_ROOT / "eval" / "tasks.example.json"),
        help="Path to a JSON task list.",
    )

    sub.add_parser("chat", help="Interactive group and direct messages")
    return parser


def main(argv: list[str] | None = None) -> None:
    load_dotenv()
    args = build_parser().parse_args(argv)
    offline = not args.online

    if args.command == "eval":
        report, _records = run_suite(
            PROJECT_ROOT,
            load_tasks(Path(args.tasks)),
            offline=offline,
            echo=True,
            provider=args.provider,
        )
        print()
        print(report)
        return

    interactive = args.command in {"task", "dm", "chat"} and not getattr(args, "scripted", False)
    human = CLIHuman() if interactive else ScriptedHuman()
    platform = Platform(
        root=PROJECT_ROOT,
        human=human,
        offline=offline,
        echo=True,
        provider=args.provider,
    )

    if args.command == "demo":
        record = platform.run_group(DEMO_GOAL, task_id="demo-fibonacci")
        _print_summary(record)
        return

    if args.command == "task":
        record = platform.run_group(args.goal)
        _print_summary(record)
        return

    if args.command == "dm":
        record = platform.run_dm(args.agent, args.goal)
        _print_summary(record)
        return

    _repl(platform)


def _repl(platform: Platform) -> None:
    print("Commands: /goal <text>, /dm <agent> <text>, /quit")
    while True:
        try:
            line = input("you> ").strip()
        except EOFError:
            print()
            return
        if line in {"/quit", "quit", "exit"}:
            return
        if line.startswith("/goal "):
            record = platform.run_group(line[6:].strip())
            _print_summary(record)
            continue
        if line.startswith("/dm "):
            _parts = line.split(maxsplit=2)
            if len(_parts) < 3:
                print("Usage: /dm <researcher|coder|reviewer> <text>")
                continue
            record = platform.run_dm(_parts[1], _parts[2])
            _print_summary(record)
            continue
        print("Use /goal, /dm, or /quit.")


if __name__ == "__main__":
    main()
